:root {
    --page: #f6f8fb;
    --surface: #ffffff;
    --surface-soft: #eef3f8;
    --ink: #17202a;
    --muted: #667085;
    --line: #d9e2ec;
    --blue: #2563eb;
    --blue-soft: #e9f0ff;
    --green: #0f9f6e;
    --orange: #c86b2c;
    --shadow-sm: 0 10px 28px rgba(23, 32, 42, 0.06);
    --shadow-md: 0 22px 55px rgba(23, 32, 42, 0.1);
    --radius: 18px;
    --transition: 180ms ease;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    scroll-behavior: smooth;
    scroll-padding-top: 92px;
}

body {
    min-height: 100vh;
    background:
        linear-gradient(180deg, #ffffff 0%, var(--page) 42%),
        var(--page);
    color: var(--ink);
    font-family: "Source Sans 3", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
    line-height: 1.65;
}

h1,
h2,
h3,
.logo-text,
.stat-number {
    font-family: Chivo, "Source Sans 3", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
}

a {
    color: inherit;
}

button,
input,
textarea {
    font: inherit;
}

.glass {
    background: var(--surface);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-sm);
}

.navbar {
    position: sticky;
    top: 0;
    z-index: 1000;
    border-bottom: 1px solid rgba(217, 226, 236, 0.86);
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(16px);
}

.nav-container {
    width: min(1180px, calc(100% - 32px));
    min-height: 72px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
}

.logo {
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 800;
}

.logo-icon {
    width: 34px;
    height: 34px;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: var(--ink);
    color: #fff;
    font-size: 0.95rem;
}

.logo-text {
    font-size: 1.05rem;
}

.nav-menu {
    display: flex;
    align-items: center;
    list-style: none;
    gap: 8px;
}

.nav-link {
    display: inline-flex;
    min-height: 38px;
    align-items: center;
    padding: 0 13px;
    border-radius: 999px;
    color: var(--muted);
    text-decoration: none;
    font-weight: 700;
    font-size: 0.92rem;
}

.nav-link:hover,
.nav-link.active {
    background: var(--surface-soft);
    color: var(--ink);
}

.btn {
    display: inline-flex;
    min-height: 46px;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 0 18px;
    border-radius: 12px;
    border: 1px solid transparent;
    text-decoration: none;
    font-weight: 800;
    transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition), background var(--transition);
}

.btn:hover {
    transform: translateY(-2px);
}

.btn-primary {
    background: var(--ink);
    color: #fff;
    box-shadow: 0 12px 30px rgba(23, 32, 42, 0.14);
}

.btn-secondary {
    background: #fff;
    color: var(--ink);
    border-color: var(--line);
}

.btn-outline {
    background: transparent;
    color: var(--ink);
    border-color: var(--line);
    border-style: dashed;
}

.btn-outline:hover {
    background: var(--surface-soft);
    border-style: solid;
}

.btn-glow,
.btn-glow:hover {
    box-shadow: 0 12px 30px rgba(23, 32, 42, 0.14);
}

.btn:hover .btn-icon {
    transform: translateX(3px);
}

.btn-icon {
    transition: transform var(--transition);
}

.btn-full {
    width: 100%;
}

.hero {
    width: min(1180px, calc(100% - 32px));
    min-height: calc(100vh - 72px);
    margin: 0 auto;
    padding: 74px 0 66px;
    display: grid;
    grid-template-columns: minmax(0, 1.03fr) minmax(360px, 0.97fr);
    gap: 48px;
    align-items: center;
}

.hero-content,
.hero-visual {
    animation: none;
}

.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    width: auto;
    padding: 8px 12px;
    border-radius: 999px;
    background: var(--blue-soft);
    border-color: #cddcff;
    color: #1d4ed8;
    box-shadow: none;
    font-size: 0.9rem;
    font-weight: 800;
}

.badge-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--green);
}

.hero-title {
    margin: 24px 0 16px;
    font-size: clamp(3rem, 7vw, 5.8rem);
    line-height: 0.96;
    letter-spacing: 0;
}

.greeting {
    display: block;
    margin-bottom: 12px;
    color: var(--muted);
    font-size: clamp(1.15rem, 2vw, 1.45rem);
    font-weight: 800;
}

.name-gradient {
    color: var(--ink);
    background: none;
    -webkit-text-fill-color: currentColor;
}

.hero-subtitle {
    margin-bottom: 14px;
    color: #184d86;
    font-size: 1.12rem;
    font-weight: 800;
}

.hero-description {
    max-width: 660px;
    color: var(--muted);
    font-size: 1.05rem;
}

.hero-buttons {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin: 30px 0 32px;
}

.hero-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
}

.stat-card {
    min-height: 108px;
    padding: 18px;
    border-radius: 16px;
    text-align: left;
    box-shadow: none;
}

.stat-card:hover,
.skill-category:hover,
.project-card:hover {
    transform: translateY(-4px);
}

.stat-number {
    color: var(--ink);
    background: none;
    -webkit-text-fill-color: currentColor;
    font-size: 2.1rem;
    font-weight: 900;
    line-height: 1;
}

.stat-label {
    margin-top: 10px;
    color: var(--muted);
    font-size: 0.9rem;
}

.profile-board {
    border-radius: 26px;
    padding: 24px;
    background:
        linear-gradient(180deg, #ffffff 0%, #f5f8fb 100%);
    box-shadow: var(--shadow-md);
}

.profile-header {
    display: flex;
    align-items: center;
    gap: 16px;
    padding-bottom: 18px;
    border-bottom: 1px solid var(--line);
}

.profile-avatar {
    width: 68px;
    height: 68px;
    display: grid;
    place-items: center;
    border-radius: 18px;
    background: var(--ink);
    color: #fff;
    font-size: 2rem;
    font-weight: 900;
}

.profile-kicker,
.card-label {
    color: var(--blue);
    font-size: 0.76rem;
    font-weight: 900;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.profile-header h2 {
    margin: 3px 0;
    font-size: 1.4rem;
}

.profile-header span,
.profile-tile span,
.profile-tile small,
.timeline-row p {
    color: var(--muted);
}

.profile-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin: 18px 0;
}

.profile-tile,
.timeline-card {
    border: 1px solid var(--line);
    background: #fff;
    border-radius: 16px;
}

.profile-tile {
    padding: 16px;
}

.profile-tile strong {
    display: block;
    margin: 5px 0 2px;
}

.timeline-card {
    display: grid;
    gap: 14px;
    padding: 18px;
}

.timeline-row {
    display: grid;
    grid-template-columns: 16px 1fr;
    gap: 10px;
}

.timeline-dot {
    width: 10px;
    height: 10px;
    margin-top: 8px;
    border-radius: 50%;
    background: var(--blue);
    box-shadow: 0 0 0 5px var(--blue-soft);
}

.profile-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 18px;
}

.profile-tags span,
.skill-tag,
.project-tags .tag {
    display: inline-flex;
    min-height: 30px;
    align-items: center;
    border-radius: 999px;
    background: var(--surface-soft);
    color: #344054;
    border: 1px solid transparent;
    font-size: 0.82rem;
    font-weight: 700;
}

.profile-tags span,
.skill-tag {
    padding: 0 11px;
}

.section {
    padding: 92px 0;
}

.section-container {
    width: min(1180px, calc(100% - 32px));
    margin: 0 auto;
}

.section-title {
    display: flex;
    justify-content: flex-start;
    align-items: flex-end;
    gap: 12px;
    margin-bottom: 28px;
    font-size: clamp(2rem, 4vw, 3.1rem);
    line-height: 1.05;
}

.plain-title {
    margin-bottom: 14px;
}

.section-kicker {
    margin-bottom: 10px;
    color: var(--blue);
    font-size: 0.82rem;
    font-weight: 900;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.title-icon {
    display: none;
}

.section-lead {
    max-width: 820px;
    margin: -12px 0 28px;
    color: var(--muted);
}

.about-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(340px, 0.72fr);
    gap: 24px;
    align-items: start;
}

.contact-grid {
    display: flex;
    justify-content: center;
}

.contact-grid .contact-info {
    max-width: 520px;
    width: 100%;
}

.about-content,
.experience-card,
.contact-info,
.skill-category {
    border-radius: var(--radius);
}

.about-heading,
.contact-heading {
    margin-bottom: 14px;
    color: var(--ink);
    background: none;
    -webkit-text-fill-color: currentColor;
    font-size: 1.6rem;
}

.about-text,
.contact-text,
.project-description {
    color: var(--muted);
}

.about-highlights {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    margin-top: 24px;
}

.highlight-item {
    min-height: 68px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 14px;
    background: #fff;
    font-weight: 800;
}

.highlight-icon {
    font-size: 1rem;
}

.experience-card {
    padding: 22px;
}

.experience-card h3 {
    margin: 7px 0;
    font-size: 1.25rem;
}

.experience-card p,
.experience-card ul {
    color: var(--muted);
}

.experience-card ul {
    display: grid;
    gap: 8px;
    padding-left: 18px;
}

.skills-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
}

.skill-category {
    padding: 22px;
    transition: transform var(--transition), box-shadow var(--transition);
}

.skill-category h3 {
    margin-bottom: 16px;
    font-size: 1.18rem;
}

.skill-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.overview-section {
    padding-top: 34px;
    padding-bottom: 34px;
}

.overview-ledger {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin-top: 20px;
    max-width: 680px;
}

.overview-card,
.case-study-card {
    background: var(--surface);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-sm);
}

.overview-card {
    min-height: 100px;
    border-radius: 16px;
    padding: 16px 20px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 16px;
    transition: all 0.2s ease;
    position: relative;
}

.overview-card:hover {
    border-color: var(--ink);
    box-shadow: var(--shadow-md);
    transform: translateY(-2px);
}

.overview-card:focus-visible {
    outline: 2px solid var(--ink);
    outline-offset: 2px;
}

.overview-card span {
    display: inline-flex;
    width: 34px;
    height: 34px;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 10px;
    background: var(--ink);
    color: #fff;
    font-weight: 900;
    font-size: 0.88rem;
}

.overview-card div {
    flex: 1;
    min-width: 0;
}

.overview-card h3 {
    margin-bottom: 2px;
    font-size: 1rem;
}

.overview-card p {
    color: var(--muted);
    font-size: 0.82rem;
    line-height: 1.4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.card-arrow {
    flex-shrink: 0;
    font-style: normal;
    font-size: 1.1rem;
    color: var(--muted);
    transition: all 0.2s ease;
}

.overview-card:hover .card-arrow {
    color: var(--ink);
    transform: translateX(3px);
}

.projects-filter {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 24px;
}

.filter-btn {
    min-height: 40px;
    border: 1px solid var(--line);
    border-radius: 999px;
    background: #fff;
    color: var(--muted);
    padding: 0 14px;
    cursor: pointer;
    font-weight: 800;
}

.filter-btn:hover,
.filter-btn.active {
    background: var(--ink);
    color: #fff;
    border-color: var(--ink);
}

.case-study-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
    margin: 0 0 22px;
}

.case-study-card {
    display: grid;
    gap: 14px;
    border-radius: 20px;
    padding: 22px;
}

.case-study-card h3 {
    margin-top: 5px;
    font-size: 1.28rem;
}

.case-study-card p {
    color: var(--muted);
}

.case-study-card a {
    width: fit-content;
    min-height: 38px;
    display: inline-flex;
    align-items: center;
    border-radius: 10px;
    background: var(--ink);
    color: #fff;
    padding: 0 13px;
    text-decoration: none;
    font-weight: 900;
    font-size: 0.86rem;
}

.case-label {
    color: var(--blue);
    font-size: 0.78rem;
    font-weight: 900;
}

.projects-grid {
    display: grid;
    grid-template-columns: repeat(12, 1fr);
    gap: 18px;
}

.project-card {
    grid-column: span 6;
    border-radius: 22px;
    overflow: hidden;
    position: relative;
    transition: transform var(--transition), box-shadow var(--transition);
}

.project-card.featured {
    grid-column: span 6;
    border: 1px solid var(--line);
    box-shadow: var(--shadow-md);
}

.project-card.featured:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-md);
}

.project-badge {
    position: absolute;
    top: 16px;
    left: 16px;
    z-index: 2;
    padding: 7px 10px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.92);
    color: var(--ink);
    box-shadow: none;
    border: 1px solid rgba(217, 226, 236, 0.8);
    font-size: 0.78rem;
    font-weight: 900;
}

.project-image {
    height: 236px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
    background:
        linear-gradient(135deg, #e8f0ff, #f1fbf7);
}

.project-card:nth-child(2n) .project-image {
    background: linear-gradient(135deg, #edf8fb, #f7f2ea);
}

.project-mockup {
    width: min(82%, 410px);
    min-height: 152px;
    padding: 16px;
    border-radius: 18px;
    background: #ffffff;
    border: 1px solid rgba(217, 226, 236, 0.95);
    box-shadow: 0 24px 48px rgba(23, 32, 42, 0.12);
}

.mockup-toolbar,
.metric-row,
.tag-row,
.weather-days,
.lab-top,
.lab-footer {
    display: flex;
    gap: 8px;
}

.mockup-toolbar span,
.metric-row span,
.tag-row span,
.weather-days span,
.lab-top span,
.lab-footer span {
    display: block;
    border-radius: 999px;
    background: #dbe7f7;
}

.mockup-toolbar span {
    width: 42px;
    height: 10px;
}

.mockup-split {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-top: 16px;
}

.mockup-split > div,
.post-card-mini,
.todo-item,
.lab-list div {
    border-radius: 12px;
    background: #eef3f8;
}

.mockup-split > div {
    min-height: 96px;
    padding: 13px;
}

.mockup-split b,
.mockup-split h4,
.weather-temp {
    color: var(--ink);
}

.mockup-split p,
.blog-mockup .post-line,
.weather-lines span {
    display: block;
    height: 8px;
    margin-top: 12px;
    border-radius: 999px;
    background: #d4dfeb;
    color: transparent;
}

.metric-row span {
    flex: 1;
    height: 28px;
}

.chart-line {
    height: 62px;
    margin: 16px 0;
    border-radius: 14px;
    background: linear-gradient(135deg, #dce9ff, #dff7ec);
}

.chart-bars {
    display: flex;
    align-items: end;
    gap: 8px;
    height: 50px;
}

.chart-bars span {
    flex: 1;
    border-radius: 8px 8px 0 0;
    background: #94bdf5;
}

.chart-bars span:nth-child(1) { height: 36%; }
.chart-bars span:nth-child(2) { height: 76%; }
.chart-bars span:nth-child(3) { height: 52%; }
.chart-bars span:nth-child(4) { height: 88%; }

.blog-mockup .post-line { width: 70%; }
.blog-mockup .post-line.wide {
    width: 94%;
    height: 18px;
}

.tag-row span {
    width: 54px;
    height: 10px;
    margin-top: 15px;
}

.post-card-mini {
    height: 52px;
    margin-top: 15px;
}

.todo-item {
    height: 26px;
    margin-bottom: 10px;
    border: 1px solid #d6e2ef;
}

.todo-item.done {
    background: #e8f7f1;
    opacity: 0.72;
}

.todo-item.high {
    background: #fff1e8;
}

.todo-meter {
    height: 12px;
    border-radius: 999px;
    background: linear-gradient(90deg, var(--green) 64%, #dbe4ec 64%);
}

.weather-temp {
    font-size: 3rem;
    font-weight: 900;
}

.weather-lines span {
    width: 76%;
}

.weather-lines span:nth-child(2) { width: 58%; }
.weather-lines span:nth-child(3) { width: 42%; }

.weather-days span {
    flex: 1;
    height: 40px;
    margin-top: 14px;
}

.lab-top span {
    height: 28px;
}

.lab-top span:first-child { flex: 1.3; }
.lab-top span:last-child { flex: 0.7; }

.lab-list {
    display: grid;
    gap: 10px;
    margin: 15px 0;
}

.lab-list div {
    height: 32px;
    border: 1px solid #d6e2ef;
}

.lab-footer span {
    flex: 1;
    height: 18px;
}

.project-overlay {
    position: absolute;
    inset: auto 16px 16px;
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    opacity: 1;
    background: transparent;
}

.btn-view-project {
    min-height: 38px;
    display: inline-flex;
    align-items: center;
    padding: 0 13px;
    border-radius: 10px;
    background: #fff;
    color: var(--ink);
    border: 1px solid var(--line);
    text-decoration: none;
    font-weight: 900;
    font-size: 0.84rem;
    box-shadow: 0 8px 20px rgba(23, 32, 42, 0.08);
}

.btn-view-project:hover {
    transform: translateY(-2px);
}

.project-content {
    padding: 22px;
}

.project-header {
    display: flex;
    justify-content: space-between;
    gap: 12px;
}

.project-title {
    margin-bottom: 8px;
    font-size: 1.35rem;
}

.featured-tag {
    height: 28px;
    display: inline-flex;
    align-items: center;
    border-radius: 999px;
    background: var(--blue-soft);
    color: var(--blue);
    padding: 0 9px;
    font-size: 0.75rem;
    font-weight: 900;
    animation: none;
}

.project-features {
    display: grid;
    gap: 8px;
    margin: 16px 0;
    list-style: none;
}

.project-features li {
    padding: 0;
    border-bottom: 0;
    color: var(--muted);
    font-size: 0.92rem;
}

.project-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.project-tags .tag {
    padding: 0 10px;
}

.tag.highlight {
    background: var(--ink);
    color: #fff;
}

.project-stats {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px solid var(--line);
}

.stat-item {
    display: inline-flex;
    gap: 7px;
    color: var(--muted);
    font-size: 0.9rem;
}

.contact-info {
    padding: 22px 0;
}

.contact-links {
    display: grid;
    gap: 12px;
}

.contact-link {
    display: flex;
    align-items: center;
    gap: 12px;
    min-height: 58px;
    padding: 0 16px;
    border-radius: 14px;
    text-decoration: none;
    color: var(--ink);
}

.contact-link:hover {
    transform: translateX(4px);
}

.link-icon {
    font-size: 1.15rem;
}

.footer {
    margin-top: 52px;
    padding: 26px 0;
    border-top: 1px solid var(--line);
    box-shadow: none;
}

.footer-content {
    width: min(1180px, calc(100% - 32px));
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 18px;
    color: var(--muted);
}

.social-links {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
}

.social-link {
    color: var(--muted);
    text-decoration: none;
    font-weight: 800;
}

.social-link:hover {
    color: var(--ink);
}

@media (max-width: 980px) {
    .hero,
    .about-grid,
    .contact-grid {
        grid-template-columns: 1fr;
    }

    .hero {
        padding-top: 46px;
        text-align: left;
    }

    .hero-visual {
        order: 0;
    }

    .skills-grid,
    .projects-grid,
    .overview-ledger,
    .case-study-grid {
        grid-template-columns: 1fr;
    }

    .project-card,
    .project-card.featured {
        grid-column: span 1;
    }

    .about-highlights {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 720px) {
    .nav-menu {
        display: none;
    }

    .hero,
    .section-container,
    .nav-container,
    .footer-content {
        width: min(100% - 22px, 1180px);
    }

    .hero-stats,
    .profile-grid,
    .about-highlights {
        grid-template-columns: 1fr;
    }

    .section {
        padding: 62px 0;
    }

    .project-image {
        height: 210px;
    }

    .project-header,
    .footer-content {
        align-items: flex-start;
        flex-direction: column;
    }
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
    }
}
