    --surface-hover: rgba(255, 255, 255, 0.92);
    --ink: #17202a;
    --ink-soft: #334155;
    --muted: #667085;
    --line: rgba(0, 0, 0, 0.08);
    --line-strong: rgba(0, 0, 0, 0.12);
    --accent: #2563eb;
    --accent-soft: #e9f0ff;
