    border-radius: 999px;
    color: var(--muted);
    font-weight: 700;
    font-size: 0.9rem;
    transition: color var(--transition), background var(--transition);
}

.nav-link:hover,
.nav-link.active {
    background: var(--accent-soft);
    color: var(--accent);
