/* ---- Custom Cursor ---- */
.cursor {
    position: fixed;
    width: 12px; height: 12px;
    border-radius: 50%;
    background: var(--accent);
    pointer-events: none;
    z-index: 99999;
    mix-blend-mode: difference;
    transform: translate(-50%, -50%);
    transition: width 0.2s, height 0.2s, background 0.2s;
}
.cursor-ring {
    position: fixed;
    width: 36px; height: 36px;
    border-radius: 50%;
    border: 1.5px solid var(--accent);
    pointer-events: none;
    z-index: 99998;
    transform: translate(-50%, -50%);
    transition: width 0.3s, height 0.3s, border-color 0.3s;
    opacity: 0.6;
}
.cursor.hover { width: 20px; height: 20px; background: #fff; }
.cursor-ring.hover { width: 52px; height: 52px; border-color: #fff; opacity: 0.9; }

/* ---- Particle Canvas ---- */
#particles {
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
}

