    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
    transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
}

