    --accent-glow: rgba(0, 212, 255, 0.25);
    --purple: #a78bfa;
    --purple-soft: rgba(167, 139, 250, 0.08);
    --green: #34d399;
    --orange: #fb923c;

    --radius-sm: 10px;
    --radius: 16px;
    --radius-lg: 22px;
