}

.hero-title {
    margin: 24px 0 16px;
    font-size: clamp(3rem, 7vw, 5.8rem);
    line-height: 0.96;
}

.greeting {
    display: block;
    margin-bottom: 12px;
    color: var(--muted);
    font-size: clamp(1.15rem, 2vw, 1.45rem);
    font-weight: 800;
}

