.nav-container {
    width: min(1180px, calc(100% - 32px));
    min-height: 72px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
}

.logo { display: flex; align-items: center; gap: 10px; font-weight: 800; }

.logo-icon {
    width: 34px; height: 34px;
    display: grid; place-items: center;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--accent), var(--purple));
    color: #fff;
    font-size: 0.95rem;
    box-shadow: 0 0 20px var(--accent-glow);
}

.nav-menu { display: flex; align-items: center; list-style: none; gap: 6px; }

.nav-link {
    display: inline-flex;
    min-height: 38px;
    align-items: center;
    padding: 0 14px;
    border-radius: 999px;
    color: var(--muted);
    font-weight: 700;
    font-size: 0.9rem;
    transition: color var(--transition), background var(--transition);
}

.nav-link:hover,
.nav-link.active {
    background: var(--accent-soft);
    color: var(--accent);
}

/* ---- Theme Toggle ---- */
.theme-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px; height: 38px;
    border-radius: 50%;
    border: 1px solid var(--line);
    background: var(--surface);
    color: var(--ink);
    font-size: 1.1rem;
    transition: all var(--transition);
}
.theme-toggle:hover {
    border-color: var(--accent);
    box-shadow: 0 0 16px var(--accent-glow);
}

/* ---- Buttons ---- */
.btn {
    display: inline-flex;
    min-height: 46px;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 0 20px;
    border-radius: 12px;
    border: 1px solid transparent;
    font-weight: 800;
    transition: transform var(--transition), box-shadow var(--transition), background var(--transition);
}

.btn:hover { transform: translateY(-2px); }

.btn-primary {
    background: linear-gradient(135deg, var(--accent), var(--purple));
    color: #fff;
    box-shadow: 0 0 30px var(--accent-glow);
    border: none;
}
.btn-primary:hover {
    box-shadow: 0 0 40px var(--accent-glow), 0 8px 24px rgba(0, 212, 255, 0.3);
}

.btn-secondary {
    background: var(--surface);
    color: var(--ink);
    border-color: var(--line-strong);
}

.btn-icon { transition: transform var(--transition); }
.btn:hover .btn-icon { transform: translateX(3px); }
.btn-full { width: 100%; }

/* ---- Hero ---- */
.hero {
    width: min(1180px, calc(100% - 32px));
    min-height: calc(100vh - 72px);
    margin: 0 auto;
    padding: 74px 0 66px;
    display: grid;
    grid-template-columns: minmax(0, 1.03fr) minmax(360px, 0.97fr);
    gap: 48px;
    align-items: center;
    position: relative;
    z-index: 1;
}

.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 14px;
    border-radius: 999px;
    background: var(--accent-soft);
    border: 1px solid rgba(0, 212, 255, 0.2);
    color: var(--accent);
    font-size: 0.88rem;
    font-weight: 800;
}

.badge-dot {
    width: 8px; height: 8px;
    border-radius: 50%;
    background: var(--green);
    animation: pulse-dot 2s ease-in-out infinite;
}

@keyframes pulse-dot {
    0%, 100% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.5); }
    50% { box-shadow: 0 0 0 8px rgba(52, 211, 153, 0); }
}

.hero-title {
    margin: 24px 0 16px;
    font-size: clamp(3rem, 7vw, 5.8rem);
    line-height: 0.96;
}

.greeting {
    display: block;
    margin-bottom: 12px;
    color: var(--muted);
    font-size: clamp(1.15rem, 2vw, 1.45rem);
    font-weight: 800;
}

.name-gradient {
    background: linear-gradient(135deg, var(--accent) 0%, var(--purple) 60%, var(--accent) 100%);
    background-size: 200% 200%;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: gradient-shift 4s ease infinite;
}

@keyframes gradient-shift {
    0%, 100% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
}

.hero-subtitle {
    margin-bottom: 14px;
    color: var(--accent);
    font-size: 1.12rem;
    font-weight: 800;
    opacity: 0.9;
}

.hero-description {
    max-width: 660px;
    color: var(--muted);
    font-size: 1.05rem;
}

.hero-buttons {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin: 30px 0 32px;
}

/* ---- Hero Proof ---- */
.hero-proof {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
}
.hero-proof > div {
    padding: 16px;
    border-radius: var(--radius);
    background: var(--surface);
    border: 1px solid var(--line);
}
.hero-proof strong {
    display: block;
    margin-bottom: 6px;
    color: var(--ink);
    font-size: 0.95rem;
}
.hero-proof span {
    color: var(--muted);
    font-size: 0.85rem;
    line-height: 1.4;
}

/* ---- Profile Board ---- */
.profile-board {
    border-radius: var(--radius-xl);
    padding: 24px;
    background: var(--surface);
    border: 1px solid var(--line);
    box-shadow: 0 0 60px rgba(0, 212, 255, 0.05);
    position: relative;
    overflow: hidden;
}
.profile-board::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--accent), var(--purple), transparent);
    opacity: 0.5;
}

.profile-header {
    display: flex;
    align-items: center;
    gap: 16px;
    padding-bottom: 18px;
    border-bottom: 1px solid var(--line);
}

.profile-avatar {
    width: 68px; height: 68px;
    display: grid; place-items: center;
    border-radius: 18px;
    background: linear-gradient(135deg, var(--accent), var(--purple));
    color: #fff;
    font-size: 2rem;
    font-weight: 900;
    box-shadow: 0 0 20px var(--accent-glow);
}

.profile-kicker, .card-label {
    color: var(--accent);
    font-size: 0.76rem;
    font-weight: 900;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.profile-header h2 { margin: 3px 0; font-size: 1.4rem; }
.profile-header span, .profile-tile span, .profile-tile small, .timeline-row p { color: var(--muted); }

.profile-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin: 18px 0;
}

.profile-tile, .timeline-card {
    border: 1px solid var(--line);
    background: var(--bg-soft);
    border-radius: var(--radius);
}

.profile-tile { padding: 16px; }
.profile-tile strong { display: block; margin: 5px 0 2px; }

.timeline-card { display: grid; gap: 14px; padding: 18px; }

.timeline-row {
    display: grid;
    grid-template-columns: 16px 1fr;
    gap: 10px;
}

.timeline-dot {
    width: 10px; height: 10px;
    margin-top: 8px;
    border-radius: 50%;
    background: var(--accent);
    box-shadow: 0 0 0 5px var(--accent-soft);
}

.profile-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 18px;
}

.profile-tags span, .skill-tag, .project-tags .tag {
    display: inline-flex;
    min-height: 30px;
    align-items: center;
    border-radius: 999px;
    background: var(--accent-soft);
    color: var(--accent);
    border: 1px solid rgba(0, 212, 255, 0.15);
    font-size: 0.82rem;
    font-weight: 700;
    padding: 0 11px;
    transition: all var(--transition);
}
.profile-tags span:hover, .skill-tag:hover, .project-tags .tag:hover {
    background: var(--accent);
    color: #08090f;
    border-color: var(--accent);
    box-shadow: 0 0 16px var(--accent-glow);
}

/* ---- Sections ---- */
.section { padding: 92px 0; position: relative; z-index: 1; }

.section-container {
    width: min(1180px, calc(100% - 32px));
    margin: 0 auto;
}

.section-title {
    display: flex;
    justify-content: flex-start;
    align-items: flex-end;
    gap: 12px;
    margin-bottom: 28px;
    font-size: clamp(2rem, 4vw, 3.1rem);
    line-height: 1.05;
}

.plain-title { margin-bottom: 14px; }

.section-kicker {
    margin-bottom: 10px;
    color: var(--accent);
    font-size: 0.82rem;
    font-weight: 900;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.title-icon { display: none; }

.section-lead {
    max-width: 820px;
    margin: -12px 0 28px;
    color: var(--muted);
}

/* ---- About ---- */
.about-grid, .contact-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(340px, 0.72fr);
    gap: 24px;
    align-items: start;
}

.about-content, .experience-card, .contact-info, .contact-form, .skill-category {
    border-radius: var(--radius);
}

.about-heading, .contact-heading {
    margin-bottom: 14px;
    background: linear-gradient(135deg, var(--accent), var(--purple));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    font-size: 1.6rem;
}

.about-text, .contact-text, .project-description { color: var(--muted); }

.about-highlights {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    margin-top: 24px;
}

.highlight-item {
    min-height: 68px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 14px;
    background: var(--surface);
    font-weight: 800;
    transition: all var(--transition);
}
.highlight-item:hover {
    border-color: var(--accent);
    box-shadow: 0 0 20px var(--accent-glow);
    transform: translateY(-2px);
}

.highlight-icon { font-size: 1rem; }

.experience-card {
    padding: 22px;
    position: relative;
    overflow: hidden;
}
.experience-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--accent), var(--purple), transparent);
    opacity: 0.4;
}
.experience-card h3 { margin: 7px 0; font-size: 1.25rem; }
.experience-card p, .experience-card ul { color: var(--muted); }
.experience-card ul { display: grid; gap: 8px; padding-left: 18px; }

/* ---- Skills ---- */
.skills-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
}

.skill-category {
    padding: 22px;
    transition: transform var(--transition), box-shadow var(--transition);
}
.skill-category:hover {
    transform: translateY(-4px);
    box-shadow: 0 0 30px var(--accent-glow);
    border-color: var(--accent);
}

.skill-category h3 { margin-bottom: 16px; font-size: 1.18rem; }

.skill-tags { display: flex; flex-wrap: wrap; gap: 8px; }

